import os

import requests
from langchain_core.tools import tool

REGISTRAR_API = "https://api.registrar.example.com/v1"
API_KEY = os.environ.get("REGISTRAR_API_KEY", "")


@tool
def transfer_domain_in(domain: str, auth_code: str, years: int) -> dict:
    if not domain or "." not in domain or " " in domain:
        return {"ok": False, "error": "invalid domain name"}
    if not auth_code or len(auth_code) < 6:
        return {"ok": False, "error": "missing or malformed auth code"}
    if years < 1 or years > 10:
        return {"ok": False, "error": "years must be between 1 and 10"}
    resp = requests.post(
        f"{REGISTRAR_API}/transfers",
        headers={"Authorization": f"Bearer {API_KEY}"},
        json={"domain": domain.lower(), "auth_code": auth_code, "years": years},
        timeout=30,
    )
    if resp.status_code >= 400:
        return {"ok": False, "error": resp.text}
    return {"ok": True, "transfer": resp.json()}

import datetime

import dns.exception
import dns.resolver
import requests


def _query(resolver_ip, hostname, record_type):
    resolver = dns.resolver.Resolver(configure=False)
    resolver.nameservers = [resolver_ip]
    resolver.lifetime = 5.0
    try:
        answer = resolver.resolve(hostname, record_type)
    except dns.resolver.NXDOMAIN:
        return [], "nxdomain"
    except dns.resolver.NoAnswer:
        return [], "no_answer"
    except dns.exception.Timeout:
        return [], "timeout"
    values = [rdata.to_text().strip('"').rstrip(".") for rdata in answer]
    return values, "ok"


def _normalize(value):
    return value.strip().strip('"').rstrip(".").lower()


def check_propagation_and_notify(hostname, record_type, expected_value, webhook_url, resolvers):
    if not resolvers:
        return {"error": "no resolvers provided"}
    expected = _normalize(expected_value)
    results = []
    for ip in resolvers:
        values, status = _query(ip, hostname, record_type.upper())
        normalized = [_normalize(v) for v in values]
        results.append(
            {
                "resolver": ip,
                "status": status,
                "values": values,
                "matches": expected in normalized,
            }
        )
    matched = sum(1 for r in results if r["matches"])
    report = {
        "hostname": hostname,
        "record_type": record_type.upper(),
        "expected": expected_value,
        "checked_at": datetime.datetime.utcnow().isoformat() + "Z",
        "matched": matched,
        "total": len(results),
        "fully_propagated": matched == len(results),
        "results": results,
    }
    with requests.Session() as session:
        session.headers.update({"Content-Type": "application/json"})
        resp = session.post(webhook_url, json=report, timeout=15)
        report["webhook_status"] = resp.status_code
    return report

import sqlite3

DB_PATH = "dns_manager.db"


def grant_zone_access(zone_name, user_email, role):
    with sqlite3.connect(DB_PATH) as conn:
        row = conn.execute(
            "SELECT id FROM zones WHERE name = ?", (zone_name.lower(),)
        ).fetchone()
        if row is None:
            return {"ok": False, "error": "zone not found"}
        conn.execute(
            "INSERT OR REPLACE INTO zone_permissions (zone_id, user_email, role) VALUES (?, ?, ?)",
            (row[0], user_email.lower(), role),
        )
    return {"ok": True, "zone_id": row[0], "user": user_email, "role": role}
